import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;
const distPath = path.join(__dirname, 'dist');

// Serve static assets generated by Vite
if (fs.existsSync(distPath)) {
  app.use(express.static(distPath));

  // Single Page Application (SPA) fallback to index.html
  app.get('*', (req, res) => {
    res.sendFile(path.join(distPath, 'index.html'));
  });
} else {
  app.get('*', (req, res) => {
    res.status(200).send(`
      <!DOCTYPE html>
      <html>
        <head><title>Grupo Marbelyst - Iniciando</title></head>
        <body style="font-family: sans-serif; text-align: center; padding: 50px;">
          <h2>Grupo Marbelyst</h2>
          <p>La aplicación se está inicializando. Por favor recarga en unos segundos.</p>
        </body>
      </html>
    `);
  });
}

app.listen(PORT, '0.0.0.0', () => {
  console.log(`Servidor Grupo Marbelyst ejecutándose en el puerto ${PORT}`);
});
